application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #536174;
  --border: #cbd5e1;
  --surface: #ffffff;
  --background: #f1f5f9;
  --accent: #1d4ed8;
  --accent-dark: #163da8;
  --danger: #b42318;
  --focus: #f59e0b;
}

body {
  margin: 0;
  min-width: 18rem;
  background: var(--background);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

.app-shell {
  width: min(100% - 2rem, 46rem);
  margin: 0 auto;
  padding: 3rem 0;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .4rem;
  color: var(--accent-dark);
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.intro {
  margin-bottom: 0;
  color: var(--muted);
}

.todo-panel {
  margin-bottom: 1.25rem;
  padding: clamp(1rem, 4vw, 1.5rem);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: .75rem;
  box-shadow: 0 .25rem 1rem rgb(15 23 42 / 5%);
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-weight: 650;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: .6rem .75rem;
  color: var(--ink);
  background: #fff;
  border: 1px solid #8795a8;
  border-radius: .4rem;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem 1rem;
  border: 0;
  border-radius: .4rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

#task-add {
  color: #fff;
  background: var(--accent);
}

#task-add:hover {
  background: var(--accent-dark);
}

button:focus-visible, input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.form-message {
  min-height: 1.5em;
  margin: .5rem 0 0;
  color: var(--danger);
  font-size: .9rem;
}

.list-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.list-heading h2 {
  margin-bottom: 0;
}

.count {
  margin: 0;
  color: var(--muted);
  font-size: .95rem;
}

.count span:first-child {
  color: var(--ink);
  font-weight: 750;
}

.task-list {
  display: grid;
  gap: .65rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .8rem;
  border: 1px solid var(--border);
  border-radius: .5rem;
}

.task-toggle {
  flex: 0 0 auto;
  width: 1.25rem;
  height: 1.25rem;
  min-height: 1.25rem;
  margin: 0;
  accent-color: var(--accent);
}

.task-text {
  flex: 1;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: var(--muted);
  text-decoration: line-through;
}

.task-delete {
  min-height: 2rem;
  padding: .35rem .6rem;
  color: var(--danger);
  background: transparent;
  border: 1px solid #e5a8a3;
  font-size: .9rem;
}

.task-delete:hover {
  color: #fff;
  background: var(--danger);
}

.empty-message {
  margin: 1.25rem 0 0;
  color: var(--muted);
  text-align: center;
}

@media (max-width:  thirtyrem) {
  .input-row {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 30rem) {
  .app-shell {
    padding: 2rem 0;
  }

  .list-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: .25rem;
  }
}

