const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.querySelector('#count-label');
const emptyMessage = document.querySelector('#empty-message');
const formMessage = document.querySelector('#form-message');

let tasks = [];
let nextTaskId = 1;

function setFormMessage(message) {
  formMessage.textContent = message;
}

function createTask(text) {
  return { id: nextTaskId++, text, completed: false };
}

function addTask(event) {
  event.preventDefault();
  const text = taskInput.value.trim();

  if (!text) {
    setFormMessage('Enter a task before adding it.');
    taskInput.focus();
    return;
  }

  tasks.push(createTask(text));
  taskInput.value = '';
  setFormMessage('');
  renderTasks();
  taskInput.focus();
}

function toggleTask(taskId) {
  const task = tasks.find((item) => item.id === taskId);
  if (task) {
    task.completed = !task.completed;
    renderTasks();
  }
}

function deleteTask(taskId) {
  tasks = tasks.filter((task) => task.id !== taskId);
  renderTasks();
}

function createTaskElement(task) {
  const item = document.createElement('li');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);
  if (task.completed) item.classList.add('completed');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.className = 'task-toggle';
  checkbox.dataset.testid = 'task-complete';
  checkbox.checked = task.completed;
  checkbox.id = `task-${task.id}`;
  checkbox.setAttribute('aria-label', `Mark ${task.text} as complete`);
  checkbox.addEventListener('change', () => toggleTask(task.id));

  const label = document.createElement('label');
  label.className = 'task-text';
  label.dataset.testid = 'task-text';
  label.htmlFor = checkbox.id;
  label.textContent = task.text;

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'task-delete';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
  deleteButton.addEventListener('click', () => deleteTask(task.id));

  item.append(checkbox, label, deleteButton);
  return item;
}

function updateCount() {
  const count = tasks.filter((task) => !task.completed).length;
  incompleteCount.textContent = String(count);
  countLabel.textContent = count === 1 ? 'incomplete task' : 'incomplete tasks';
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  emptyMessage.hidden = tasks.length > 0;
  updateCount();
}

taskForm.addEventListener('submit', addTask);
renderTasks();
